// Transformar y guardar clientes de Supabase
const staticData = $getWorkflowStaticData('global');
const clientes = [];

for (const item of $input.all()) {
  const c = item.json;

  // Solo procesar si tiene teléfono válido
  if (!c.phone || c.phone.trim() === '') continue;

  // Normalizar teléfono (remover +, espacios, guiones)
  const telefonoNormalizado = c.phone.replace(/[^0-9]/g, '');

  clientes.push({
    supabase_id: c.id,
    telefono: telefonoNormalizado,
    nombre: c.name || null,
    email: c.email || null,
    direccion: c.address || null,
    ciudad: c.city || 'Bogotá',
    total_pedidos: c.total_orders || 0,
    total_gastado: c.total_spent || 0,
    is_active: c.is_active !== false,
    synced_at: new Date().toISOString()
  });
}

// Guardar en memoria estática
staticData.clientesParaSync = clientes;
staticData.totalClientes = clientes.length;

return [{ json: { mensaje: `${clientes.length} clientes listos para sincronizar` } }];

// Recuperar clientes y generar UPSERTs
const staticData = $getWorkflowStaticData('global');
const clientes = staticData.clientesParaSync || [];

if (clientes.length === 0) {
  return [{ json: { mensaje: 'No hay clientes para sincronizar', total: 0 } }];
}

// Limpiar memoria
delete staticData.clientesParaSync;

// Retornar clientes como items individuales para UPSERT
return clientes.map(c => ({ json: c }));
